import React, { useEffect, useState } from "react";
import { useSelector, useDispatch } from "react-redux";
import { close } from "../../redux/reducer/ProductStockReducer";
import { openSuccessTicker } from "../../redux/reducer/SuccessTickerReducer";
import http from "../../services/utility";
import { apisPath } from "../../utils/path";
import { openTicker } from "../../redux/reducer/ErrorTickerReducer";

export default function AddStock() {
  const isOpen = useSelector((state) => state?.productStock?.isOpen);
  const id = useSelector((state) => state?.productStock?.id);
  const dispatch = useDispatch();
  const [stockQty, setStockQty] = useState(0);

  const handleBackgroundClick = (e) => {
    if (e?.target?.classList.contains("add_stock")) {
      dispatch(close());
    }
  };

  const AddStock = async () => {
    await http
      .put(`${apisPath?.admin?.stockUpdate}?id=${id}&qty=${stockQty}`)
      .then(async (res) => {
        // console.log(res?.data?.message);
        dispatch(
          openSuccessTicker({ title: "Success", body: res?.data?.message })
        );
        dispatch(close());
      })
      .catch((err) => {
        // console.log(err);
        dispatch(
          openTicker({ title: "Error", body: err?.response?.data?.message })
        );
      });
  };

  if (isOpen) {
    return (
      <div className="add_stock" onClick={handleBackgroundClick}>
        <div className="add_stock__content">
          <h2>Add Stock</h2>
          <input
            type="text"
            placeholder="Enter here"
            onChange={(e) => {
              setStockQty(e?.target?.value);
            }}
          />
          <div className="add_stock__content__buttons">
            <button className="button-red" onClick={AddStock}>
              Add
            </button>
          </div>
        </div>
      </div>
    );
  } else {
    return null;
  }
}
