import React, { useEffect } from "react";
import { useSelector, useDispatch } from "react-redux";
import { close } from "../../redux/reducer/LogoutReducer";
import { logout } from "../../redux/reducer/LoginReducer";
import { openSuccessTicker } from "../../redux/reducer/SuccessTickerReducer";

export default function Logout() {
  const isLogoutOpen = useSelector((state) => state?.logout?.isOpen);
  const dispatch = useDispatch();

  const handleBackgroundClick = (e) => {
    if (e?.target?.classList.contains("logout")) {
      dispatch(close());
    }
  };

  if (isLogoutOpen) {
    return (
      <div className="logout" onClick={handleBackgroundClick}>
        <div className="logout__content">
          <h2>Logout</h2>
          <p>
            You'll get logged out from this device and browser. Do you still
            want to continue?
          </p>
          <div className="logout__content__buttons">
            <button
              className="button-red"
              onClick={() => {
                dispatch(
                  openSuccessTicker({
                    title: "Success",
                    body: "Successfully Logout",
                  })
                );
                localStorage.setItem("userLogin", false);
                dispatch(close());
                dispatch(logout());
              }}
            >
              Logout
            </button>
            <button
              className="button-border-red"
              onClick={() => dispatch(close())}
            >
              Cancel
            </button>
          </div>
        </div>
      </div>
    );
  } else {
    return null;
  }
}
