import React, { useEffect, useState } from "react";
import { useSelector, useDispatch } from "react-redux";
import { close } from "../../redux/reducer/ChangePasswordReducer";
import { openSuccessTicker } from "../../redux/reducer/SuccessTickerReducer";
import { openTicker } from "../../redux/reducer/ErrorTickerReducer";
import { apisPath } from "../../utils/path";
import http from "../../services/utility";

export default function Change_Password() {
  const [password, setPassword] = useState("");
  const [rePassword, setRePassword] = useState("");
  const isLogoutOpen = useSelector((state) => state?.changePassword?.isOpen);
  const username = useSelector((state) => state?.login?.username);
  const dispatch = useDispatch();

  const handleBackgroundClick = (e) => {
    if (e?.target?.classList.contains("add_stock")) {
      dispatch(close());
    }
  };

  const changePassword = async () => {
    if (password !== rePassword) {
      dispatch(
        openTicker({ title: "Error", body: "Both Password Should be Matched" })
      );
    } else {
      await http
        .post(apisPath?.admin?.resetPassword, {
          identifier: username,
          newPassword: password,
        })
        .then((res) => {
          // console.log(res);
          dispatch(close());
          dispatch(
            openSuccessTicker({ title: "Success", body: res?.data?.message })
          );
        })
        .catch((err) => {
          // console.log(err);
          dispatch(
            openTicker({ title: "Error", body: err?.response?.data?.message })
          );
        });
    }
  };

  if (isLogoutOpen) {
    return (
      <div className="add_stock" onClick={handleBackgroundClick}>
        <div className="add_stock__content">
          <h2>New Password</h2>
          <input
            type="text"
            placeholder="Enter New Password"
            onChange={(e) => {
              setPassword(e?.target?.value);
            }}
          />
          <input
            type="text"
            placeholder="Enter New Password Again"
            onChange={(e) => {
              setRePassword(e?.target?.value);
            }}
          />
          <div className="add_stock__content__buttons">
            <button className="button-red" onClick={changePassword}>
              Change Password
            </button>
          </div>
        </div>
      </div>
    );
  } else {
    return null;
  }
}
